/**
 * Write a c++ function to remove first and last occurrence of a given character from the string.
 * > removeOcc(string("hello"), string("l"))
 * string("heo")
 * > removeOcc(string("abcda"), string("a"))
 * string("bcd")
 * > removeOcc(string("PHP"), string("P"))
 * string("H")
 */
string removeOcc(string s, string ch) {
    int n = s.size();
    int m = ch.size();
    if (n == 0 || m == 0) return s;
    int i = 0, j = 0;
    while (i < n && j < m) {
        if (s[i] == ch[j]) {
            i++;
            j++;
        } else {
            i++;
        }
    }
    if (j == m) {
        s.erase(i - j, j);
        return s;
    }
    i = n - 1;
    j = m - 1;
    while (i >= 0 && j >= 0) {
        if (s[i] == ch[j]) {
            i--;
            j--;
        } else {
            i--;
        }
    }
    if (j == -1) {
        s.erase(i + 1, n - i - 1);
        return s;
    }
    return s;
}
