/**
 * Write a function to sort a given matrix in ascending order according to the sum of its rows.
 * > sortMatrix(vector<vector<int>>{{1, 2, 3}, {2, 4, 5}, {1, 1, 1}})
 * {{1, 1, 1}, {1, 2, 3}, {2, 4, 5}}
 * > sortMatrix(vector<vector<int>>{{1, 2, 3}, {-2, 4, -5}, {1, -1, 1}})
 * {{-2, 4, -5}, {1, -1, 1}, {1, 2, 3}}
 * > sortMatrix(vector<vector<int>>{{5, 8, 9}, {6, 4, 3}, {2, 1, 4}})
 * {{2, 1, 4}, {6, 4, 3}, {5, 8, 9}}
 */
vector<vector<int>> sortMatrix(vector<vector<int>> m) {
    int n = m.size();
    int mx = INT_MIN;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            mx = max(mx, m[i][j]);
        }
    }
    vector<int> v(n * n, 0);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            v[i * n + j] = m[i][j];
        }
    }
    sort(v.begin(), v.end());
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            m[i][j] = v[i * n + j];
        }
    }
    return m;
}
