/**
 * Write a function to check if the given number is woodball or not.
 * > isWoodall(383)
 * true
 * > isWoodall(254)
 * false
 * > isWoodall(200)
 * false
 */
bool isWoodall(int x) {
    int sum = 0;
    while (x > 0) {
        int lastDigit = x % 10;
        if (lastDigit == 0) {
            return false;
        }
        sum += lastDigit;
        x /= 10;
    }
    return sum == 10;
}
