/**
 * Write a function to find the first duplicate element in a given array of integers.
 * > findFirstDuplicate(vector<int>{1, 2, 3, 4, 4, 5})
 * 4
 * > findFirstDuplicate(vector<int>{1, 2, 3, 4})
 * -1
 * > findFirstDuplicate(vector<int>{1, 1, 2, 3, 3, 2, 2})
 * 1
 */
int findFirstDuplicate(vector<int> nums) {
    int n = nums.size();
    for (int i = 0; i < n; i++) {
        int j = nums[i];
        if (j < 0 || j >= n) continue;
        if (nums[j] == j) continue;
        swap(nums[i], nums[j]);
        i--;
    }
    for (int i = 0; i < n; i++) {
        if (nums[i] != i) return nums[i];
    }
    return -1;
}
