/**
 * Write a function to convert the given binary number to its decimal equivalent.
 * > binaryToDecimal(100)
 * 4
 * > binaryToDecimal(1011)
 * 11
 * > binaryToDecimal(1101101)
 * 109
 */
int binaryToDecimal(int binary) {
    int decimal = 0;
    int base = 1;
    while (binary > 0) {
        int rem = binary % 10;
        decimal += rem * base;
        base *= 2;
        binary /= 10;
    }
    return decimal;
}
