 * 120
 */
int findProduct(vector<int> arr, int n) {
    int res = 1;
    for (int i = 0; i < n; i++) {
        res *= arr[i];
    }
    int prod = 1;
    for (int i = 0; i < n; i++) {
        if (arr[i] != arr[i + 1]) {
            prod *= arr[i];
        }
    }
    return res / prod;
}
