 * {1}
 * > func(vector<vector<int>>{{1, 2, 6}, {1, 3, 4, 5, 7, 8}, {1, 3, 5, 6, 8, 9}, {2, 5, 7, 11}, {1, 4, 7, 8, 12}}, 5)
 * {6, 5, 7, 8, 1}
 */
vector<int> func(vector<vector<int>> nums, int k) {
    priority_queue<pair<int, int>> pq;
    unordered_map<int, int> mp;
    for (auto &nums_i : nums) {
        for (auto &num : nums_i) {
            mp[num]++;
        }
    }
    for (auto &[num, count] : mp) {
        pq.push({count, num});
    }
    vector<int> res;
    while (k--) {
        res.push_back(pq.top().second);
        pq.pop();
    }
    return res;
}
