 * 2
 * > computeLastDigit(6, 8)
 * 6
 * > computeLastDigit(1, 2)
 * 2
 */
int computeLastDigit(int a, int b) {
    int aFactorial = 1;
    int bFactorial = 1;
    int lastDigit = 0;
    while (a > 0) {
        aFactorial *= a;
        a--;
    }
    while (b > 0) {
        bFactorial *= b;
        b--;
    }
    while (aFactorial > 0) {
        lastDigit = aFactorial % 10;
        aFactorial /= 10;
    }
    while (bFactorial > 0) {
        lastDigit = bFactorial % 10;
        bFactorial /= 10;
    }
    return lastDigit;
}
