 * > countingSort(vector<int>{12, 9, 28, 33, 69, 45})
 * {9, 12, 28, 33, 45, 69}
 * > countingSort(vector<int>{8, 4, 14, 3, 2, 1})
 * {1, 2, 3, 4, 8, 14}
 */
vector<int> countingSort(vector<int> myList) {
    vector<int> result;
    int max = *max_element(myList.begin(), myList.end());
    vector<int> count(max + 1, 0);
    for (int i = 0; i < myList.size(); i++) {
        count[myList[i]]++;
    }
    for (int i = 1; i < count.size(); i++) {
        count[i] += count[i - 1];
    }
    for (int i = myList.size() - 1; i >= 0; i--) {
        result[count[myList[i]] - 1] = myList[i];
        count[myList[i]]--;
    }
    return result;
}
