 * {13, 15, 47, 99}
 */
vector<int> combSort(vector<int> nums) {
    int gap = nums.size();
    bool swapped = true;
    while (gap > 1 || swapped) {
        if (gap > 1) {
            gap = (gap * 10) / 13;
        }
        swapped = false;
        for (int i = 0; i < nums.size() - gap; i++) {
            if (nums[i] > nums[i + gap]) {
                swap(nums[i], nums[i + gap]);
                swapped = true;
            }
        }
    }
    return nums;
}
