/**
 * Write a c++ function to count the number of squares in a rectangle.
 * > countSquares(4, 3)
 * 20
 * > countSquares(2, 2)
 * 5
 * > countSquares(1, 1)
 * 1
 */
int countSquares(int m, int n) {
    int dp[m+1][n+1];
    for(int i=0; i<=m; i++) {
        for(int j=0; j<=n; j++) {
            if(i==0 || j==0) {
                dp[i][j] = 0;
            } else if(i==1 || j==1) {
                dp[i][j] = 1;
            } else {
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + 1;
            }
        }
    }
    return dp[m][n];
}
