 * 36
 */
int kthElement(vector<int> arr, int n, int k) {
    int left = 0, right = n - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (k == mid + 1) {
            return arr[mid];
        }
        if (k < mid + 1) {
