 * 1
 */
int search(vector<int> arr, int n) {
    int left = 0, right = arr.size() - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == n) {
            return n;
        }
        if (arr[mid] < n) {
            left = mid + 1;
        } else {
