 * 53
 */
int maxPathSum(vector<vector<int>> tri, int m, int n) {
    int dp[m][n];
    dp[0][0] = tri[0][0];
    for (int i = 1; i < m; i++) {
        dp[i][0] = dp[i - 1][0] + tri[i][0];
    }
    for (int i = 1; i < n; i++) {
        dp[0][i] = dp[0][i - 1] + tri[0][i];
    }
    for (int i = 1; i < m; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + tri[i][j];
        }
    }
    return dp[m - 1][n - 1];
}
