    for (int i = 0; i <= n; i++) {
        dp[i][i] = 1;
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < i; j++) {
            if (arr[i] - arr[j] == 1) {
                dp[i][j] = dp[i-1][j] + 1;
            }
        }
    }
    int max = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            max = max > dp[j][i] ? max : dp[j][i];
        }
    }
    return max;
}
