 * > mergeSort(vector<int>{7, 25, 45, 78, 11, 33, 19})
 * {7, 11, 19, 25, 33, 45, 78}
 * > mergeSort(vector<int>{3, 1, 4, 9, 8})
 * {1, 3, 4, 8, 9}
 */
vector<int> mergeSort(vector<int> x) {
    if (x.size() == 1) {
        return x;
    }
    int mid = x.size() / 2;
    vector<int> left(x.begin(), x.begin() + mid);
    vector<int> right(x.begin() + mid, x.end());
    return merge(mergeSort(left), mergeSort(right));
}

vector<int> merge(vector<int> left, vector<int> right) {
    vector<int> result;
    int i = 0, j = 0;
    while (i < left.size() && j < right.size()) {
        if (left[i] < right[j]) {
            result.push_back(left[i++]);
        } else {
            result.push_back(right[j++]);
        }
    }
    while (i < left.size()) {
        result.push_back(left[i++]);
    }
    while (j < right.size()) {
        result.push_back(right[j++]);
    }
    return result;
}
