 * false
 * > prodSquare(16)
 * true
 */
bool prodSquare(int n) {
    int sqrt = sqrt(n);
    if (sqrt * sqrt == n) {
        return true;
    }
    for (int i = 1; i <= sqrt; i++) {
        int j = sqrt - i;
        if (i * i + j * j == n) {
