    double area = 0;
    for (int i = 1; i <= a; i++) {
        for (int j = 1; j <= b; j++) {
            double x = (a * a * j * j) / (i * i);
            double y = (b * b * i * i) / (j * j);
            double z = (a * a * b * b) / (x * y);
