    heap[0] = a;
    int i = 0;
    while (i < n) {
        int l = 2 * i + 1;
        int r = 2 * i + 2;
        int min = i;
        if (l < n && heap[l] < heap[min]) {
            min = l;
        }
        if (r < n && heap[r] < heap[min]) {
            min = r;
        }
        if (min != i) {
            swap(heap[i], heap[min]);
            i = min;
        } else {
            break;
        }
    }
    return heap;
}
