    int dp[n+1][k+1];
    for(int i=0; i<=n; i++) {
        dp[i][0] = 1;
    }
    for(int i=1; i<=k; i++) {
        dp[1][i] = 1;
    }
    for(int i=2; i<=n; i++) {
        for(int j=1; j<=k; j++) {
            dp[i][j] = dp[i-1][j-1] + dp[i-1][j];
        }
    }
    return dp[n][k];
}
