 */
int findElement(vector<int> arr, vector<vector<int>> ranges, int rotations, int index) {
    int n = arr.size();
    int start = ranges[0][0], end = ranges[0][1];
    int mid = (start + end) / 2;
    int ans = -1;
    while (start <= end) {
        mid = (start + end) / 2;
        if (mid == arr[mid]) {
            ans = mid;
            break;
        }
        if (mid < arr[mid]) {
            end = mid - 1;
        } else {
            start = mid + 1;
        }
    }
    if (ans == -1) {
        return -1;
    }
    int rotatedIndex = (index + rotations) % n;
    if (rotatedIndex < ans) {
        return arr[rotatedIndex];
    }
    return findElement(arr, ranges, rotations + 1, rotatedIndex);
}
