 * 7
 * > maxSumIncreasingSubseq(vector<int>{11, 15, 19, 21, 26, 28, 31}, 7, 2, 4)
 * 71
 */
int maxSumIncreasingSubseq(vector<int> a, int n, int index, int k) {
    int dp[n+1][n+1];
    int maxSum = INT_MIN;
    for(int i=1; i<=n; i++) {
        dp[i][i] = a[i-1];
        for(int j=i+1; j<=n; j++) {
            if(a[j-1] > a[i-1]) {
                dp[i][j] = max(dp[i][j-1], dp[i+1][j]);
            } else {
                dp[i][j] = dp[i][j-1];
            }
        }
    }
    for(int i=1; i<=n; i++) {
        if(i >= index && i <= k) {
            maxSum = max(maxSum, dp[index][i]);
        }
    }
    return maxSum;
}
