 * 0
 */
int findRotationCount(vector<int> a) {
    int n = a.size();
    int l = 0, r = n - 1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (a[mid] > a[mid + 1]) {
            return mid + 1;
        }
        if (a[mid] < a[mid - 1]) {
            return n - mid;
        }
        if (a[l] <= a[mid]) {
            l = mid + 1;
        } else {
            r = mid - 1;
        }
    }
    return 0;
}
