 * 70
 * > getMaxgold(vector<vector<int>>{{4, 9}, {3, 7}}, 2, 2)
 * 13
 */
int getMaxgold(vector<vector<int>> gold, int m, int n) {
    int dp[m][n];
    memset(dp, 0, sizeof(dp));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (i == 0 && j == 0) {
                dp[i][j] = gold[i][j];
            } else if (i == 0) {
                dp[i][j] = max(dp[i][j - 1], gold[i][j]);
            } else if (j == 0) {
                dp[i][j] = max(dp[i - 1][j], gold[i][j]);
            } else {
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + gold[i][j];
            }
        }
    }
    return dp[m - 1][n - 1];
}
