 * 2
 */
int maxProfit(vector<int> price, int k) {
    int n = price.size();
    if (n == 0 || k == 0) return 0;
    if (k >= n / 2) {
        int max_profit = 0;
        for (int i = 1; i < n; i++) {
            max_profit += max(0, price[i] - price[i - 1]);
        }
        return max_profit;
    }

    vector<vector<int>> dp(k + 1, vector<int>(n, 0));
    for (int i = 1; i < n; i++) {
        dp[1][i] = max(dp[1][i - 1], price[i] - price[i - 1]);
    }
    for (int i = 2; i <= k; i++) {
        for (int j = i; j < n; j++) {
            dp[i][j] = max(dp[i][j - 1], dp[i - 1][j - 1] + price[j] - price[j - i]);
        }
    }
    return dp[k][n - 1];
}
