 * > radixSort(vector<int>{9, 11, 8, 7, 3, 2})
 * {2, 3, 7, 8, 9, 11}
 * > radixSort(vector<int>{36, 12, 24, 26, 29})
 * {12, 24, 26, 29, 36}
 */
vector<int> radixSort(vector<int> nums) {
    int max = *max_element(nums.begin(), nums.end());
    int maxDigit = 0;
    while (max > 0) {
        max /= 10;
        maxDigit++;
    }
    vector<int> buckets[10];
    for (int i = 0; i < maxDigit; i++) {
        for (int j = 0; j < nums.size(); j++) {
            int digit = (nums[j] / (int)pow(10, i)) % 10;
            buckets[digit].push_back(nums[j]);
        }
        int index = 0;
        for (int j = 0; j < 10; j++) {
            for (int k = 0; k < buckets[j].size(); k++) {
                nums[index++] = buckets[j][k];
            }
            buckets[j].clear();
        }
    }
    return nums;
}
