 * > sqrtRoot(4)
 * 2
 * > sqrtRoot(16)
 * 4
 * > sqrtRoot(400)
 * 20
 */
int sqrtRoot(int num) {
    int low = 1, high = num, mid;
    while (low <= high) {
        mid = (low + high) / 2;
        if (mid * mid == num) {
            return mid;
        } else if (mid * mid < num) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return -1;
}
