 * 5
 */
int lbs(vector<int> arr) {
    int n = arr.size();
    vector<int> l(n, 1);
    vector<int> r(n, 1);
    int ans = 1;
    for (int i = 1; i < n; i++) {
        int j = i - 1;
        while (j >= 0 && arr[i] > arr[j]) {
            l[i] = max(l[i], r[j] + 1);
            j = l[j] - 1;
        }
        ans = max(ans, l[i]);
    }
    for (int i = n - 2; i >= 0; i--) {
        int j = i + 1;
        while (j < n && arr[i] > arr[j]) {
            r[i] = max(r[i], l[j] + 1);
            j = r[j] - 1;
        }
        ans = max(ans, r[i]);
    }
    return ans;
}
