 * 10
 */
int maxSumIncreasingSubsequence(vector<int> arr, int n) {
    int dp[n];
    dp[0] = arr[0];
    int maxSum = dp[0];
    for (int i = 1; i < n; i++) {
        dp[i] = max(arr[i], dp[i - 1] + arr[i]);
        maxSum = max(maxSum, dp[i]);
    }
    return maxSum;
}
