 * 2
 * > minCoins(vector<int>{4, 5, 6, 7, 8, 9}, 6, 9)
 * 1
 * > minCoins(vector<int>{1, 2, 3}, 3, 4)
 * 2
 */
int minCoins(vector<int> coins, int m, int v) {
    int n = coins.size();
    vector<vector<int>> dp(n+1, vector<int>(v+1, INT_MAX));
    dp[0][0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= v; j++) {
            dp[i][j] = dp[i-1][j];
            if (j >= coins[i-1]) {
                dp[i][j] = min(dp[i][j], dp[i-1][j-coins[i-1]] + 1);
            }
        }
    }
    return dp[n][v];
}
