 * > findMax(vector<int>{3, 4, 5, 2, 1}, 0, 4)
 * 5
 * > findMax(vector<int>{1, 2, 3}, 0, 2)
 * 3
 */
int findMax(vector<int> arr, int low, int high) {
    if (low > high) {
        return -1;
    }
    int mid = (low + high) / 2;
    if (arr[mid] > arr[mid + 1]) {
        return arr[mid];
    }
    if (arr[mid] < arr[mid - 1]) {
        return arr[mid];
    }
    if (arr[mid] > arr[low]) {
        return findMax(arr, low, mid - 1);
    }
    return findMax(arr, mid + 1, high);
}
