 * 3
 * > findMaxLength(vector<vector<int>>{{7}, {22, 23}, {13, 14, 15}, {10, 20, 30, 40, 50}})
 * 5
 */
int findMaxLength(vector<vector<int>> lst) {
    int n = lst.size();
    int m = lst[0].size();
    vector<int> dp(m, 0);
    int max_len = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (lst[i][j] == 1) {
                dp[j]++;
            } else {
                dp[j] = 0;
            }
            max_len = max(max_len, dp[j]);
        }
    }
    return max_len;
}
